const data = msg.payload;

/* Never delete anything if ArcGIS did not give us a valid feature list. */
if (!data || !Array.isArray(data.features)) {
    node.error("No valid incident features returned from ArcGIS - NOT deleting existing fires");
    return null;
}

const previous = context.get("incidentUids") || {};
const current = {};

let sent = 0;
let deleted = 0;

node.status({fill:"green",shape:"dot",text:data.features.length + " incidents"});

for (const f of data.features) {

    if (!f.geometry) continue;

    const lat = Number(f.geometry.y);
    const lon = Number(f.geometry.x);
    const a = f.attributes || {};

    if (!Number.isFinite(lat) || !Number.isFinite(lon)) continue;

    const name = String(a.IncidentName || "Wildfire");

    const id = String(
        a.UniqueFireIdentifier ||
        a.IrwinID ||
        a.GlobalID ||
        a.OBJECTID ||
        name
    ).replace(/[^A-Za-z0-9_.:-]/g,"_");

    const uid = "ArcGIS.Wildfire." + id;

    current[uid] = true;

    const now = new Date();
    const time = now.toISOString();
    const stale = new Date(now.getTime() + 15 * 60 * 1000).toISOString();

    const remarks = [
        "Incident: " + name,
        "Daily Acres: " + value(a.DailyAcres),
        "Calculated Acres: " + value(a.CalculatedAcres),
        "Percent Contained: " + value(a.PercentContained),
        "County: " + value(a.POOCounty),
        "State: " + value(a.POOState),
        "Cause: " + value(a.FireCause),
        "Personnel: " + value(a.TotalIncidentPersonnel),
        "Discovery: " + value(a.FireDiscoveryDateTime)
    ].join(" | ");

    const cot =
`<?xml version="1.0" standalone="yes"?>
<event version="2.0" uid="${xml(uid)}" type="a-.-X-i-f-w" how="m-g" time="${time}" start="${time}" stale="${stale}">
<point lat="${lat}" lon="${lon}" hae="0" ce="9999999" le="9999999"/>
<detail>
<contact callsign="${xml(name)}"/>
<remarks>${xml(remarks)}</remarks>
</detail>
</event>`;

    node.send({payload:cot});
    sent++;
}

/*
 * DELETE INCIDENTS THAT DISAPPEARED FROM ARCGIS
 */
for (const uid of Object.keys(previous)) {

    if (current[uid]) continue;

    const now = new Date();
    const time = now.toISOString();

    const deleteCot =
`<?xml version="1.0" standalone="yes"?>
<event version="2.0" uid="${xml(uid + ".delete")}" type="t-x-d-d" how="m-g" time="${time}" start="${time}" stale="${new Date(Date.now() + 2 * 60 * 1000).toISOString()}">
<point lat="0" lon="0" hae="0" ce="9999999" le="9999999"/>
<detail>
<link uid="${xml(uid)}" type="none" relation="none"/>
<__forcedelete/>
</detail>
</event>`;

    node.send({payload:deleteCot});
    deleted++;
}

context.set("incidentUids", current);

node.status({
    fill:"green",
    shape:"dot",
    text:`${sent} current / ${deleted} deleted`
});

if (deleted > 0) {
    node.warn(`Removed ${deleted} wildfire incident(s) no longer in ArcGIS`);
}

return null;

function value(v) {
    return v === null || v === undefined || v === "" ? "N/A" : String(v);
}

function xml(v) {
    return String(v)
        .replace(/&/g,"&amp;")
        .replace(/</g,"&lt;")
        .replace(/>/g,"&gt;")
        .replace(/"/g,"&quot;")
        .replace(/'/g,"&apos;");
}

const data = msg.payload;

/* Never delete existing lines if ArcGIS did not return valid data. */
if (!data || !Array.isArray(data.features)) {
    node.error("No valid perimeter features returned from ArcGIS - NOT deleting existing perimeters");
    return null;
}

const previous = context.get("perimeterUids") || {};
const current = {};
const perIncident = {}; // count perimeter features per incident this poll

let features = 0;
let rings = 0;
let vertices = 0;
let sent = 0;
let deleted = 0;

for (const f of data.features) {

    const a = f.attributes || {};
    const g = f.geometry;

    if (!g || !Array.isArray(g.rings)) continue;

    /* Only actual wildfire perimeters. */
    const category = String(a.FeatureCategory || "");

    if (
        category !== "Wildfire Daily Fire Perimeter" &&
        category !== ""
    ) {
        continue;
    }

    features++;

    const name = String(a.IncidentName || "Wildfire Perimeter");

    // IRWINID is the permanent incident ID; GeometryID changes every time the
    // perimeter is re-mapped, which made TAK stack a new copy each update.
    const perimeterBase = String(
        a.IRWINID ||
        a.GeometryID ||
        a.GlobalID ||
        a.OBJECTID ||
        name
    ).replace(/[^A-Za-z0-9_.:-]/g,"_");
    perIncident[perimeterBase] = (perIncident[perimeterBase] || 0) + 1;
    const perimeterId = perimeterBase + (perIncident[perimeterBase] > 1 ? ".P" + perIncident[perimeterBase] : "");

    for (let r = 0; r < g.rings.length; r++) {

        const ring = g.rings[r];

        if (!Array.isArray(ring) || ring.length < 3) continue;

        const uid =
            `ArcGIS.Wildfire.Perimeter.${perimeterId}.R${r}`;

        current[uid] = true;
        rings++;

        const points = [];
        let centerLat = 0;
        let centerLon = 0;
        let count = 0;

        for (const xy of ring) {

            if (!Array.isArray(xy) || xy.length < 2) continue;

            const lon = Number(xy[0]);
            const lat = Number(xy[1]);

            if (!Number.isFinite(lat) || !Number.isFinite(lon)) continue;

            points.push(`${lat},${lon},0`);

            centerLat += lat;
            centerLon += lon;
            count++;
        }

        if (count < 3) continue;

        centerLat /= count;
        centerLon /= count;

        /* Close the ring if necessary. */
        const first = ring[0];
        const last = ring[ring.length - 1];

        if (Array.isArray(first) && Array.isArray(last)) {

            const flon = Number(first[0]);
            const flat = Number(first[1]);
            const llon = Number(last[0]);
            const llat = Number(last[1]);

            if (
                Number.isFinite(flat) &&
                Number.isFinite(flon) &&
                (flat !== llat || flon !== llon)
            ) {
                points.push(`${flat},${flon},0`);
            }
        }

        vertices += points.length;

        const now = new Date();
        const time = now.toISOString();
        const stale = new Date(now.getTime() + 15 * 60 * 1000).toISOString();

        const links = points.map(p =>
            `<link point="${p}"/>`
        ).join("\n");

        const remarks = [
            "Incident: " + value(a.IncidentName),
            "GIS Acres: " + value(a.GISAcres),
            "Category: " + value(a.FeatureCategory),
            "Map Method: " + value(a.MapMethod),
            "Geometry ID: " + value(a.GeometryID),
            "Polygon Date: " + value(a.PolygonDateTime),
            "Current Date: " + value(a.DateCurrent)
        ].join(" | ");

        const cot =
`<?xml version="1.0" standalone="yes"?>
<event version="2.0" uid="${xml(uid)}" type="u-d-f" how="m-g" time="${time}" start="${time}" stale="${stale}">
<point lat="${centerLat}" lon="${centerLon}" hae="0" ce="9999999" le="9999999"/>
<detail>
${links}
<strokeColor value="-65536"/>
<strokeWeight value="4.0"/>
<fillColor value="1073741824"/>
<contact callsign="${xml(name + " Perimeter")}"/>
<remarks>${xml(remarks)}</remarks>
</detail>
</event>`;

        node.send({payload:cot});
        sent++;
    }
}

/*
 * DELETE PERIMETER RINGS THAT NO LONGER EXIST IN ARCGIS
 */
for (const uid of Object.keys(previous)) {

    if (current[uid]) continue;

    const now = new Date();
    const time = now.toISOString();

    const deleteCot =
`<?xml version="1.0" standalone="yes"?>
<event version="2.0" uid="${xml(uid + ".delete")}" type="t-x-d-d" how="m-g" time="${time}" start="${time}" stale="${new Date(Date.now() + 2 * 60 * 1000).toISOString()}">
<point lat="0" lon="0" hae="0" ce="9999999" le="9999999"/>
<detail>
<link uid="${xml(uid)}" type="none" relation="none"/>
<__forcedelete/>
</detail>
</event>`;

    node.send({payload:deleteCot});
    deleted++;
}

context.set("perimeterUids", current);

node.status({
    fill:"green",
    shape:"dot",
    text:`${sent} lines / ${vertices} vertices / ${deleted} deleted`
});

node.warn(
    `FIRE PERIMETERS: ${features} features, ${rings} rings, ${vertices} vertices, ${sent} sent, ${deleted} deleted`
);

return null;

function value(v) {
    return v === null || v === undefined || v === "" ? "N/A" : String(v);
}

function xml(v) {
    return String(v)
        .replace(/&/g,"&amp;")
        .replace(/</g,"&lt;")
        .replace(/>/g,"&gt;")
        .replace(/"/g,"&quot;")
        .replace(/'/g,"&apos;");
}
